create table if not exists public.organization_directory (id uuid primary key default gen_random_uuid(),organization_id uuid not null unique references public.organizations(id) on delete cascade,name text not null,slug text not null unique,organization_type text not null,province_id uuid references public.provinces(id) on delete set null,city text,website text,description text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists organization_directory_province_idx on public.organization_directory(province_id,is_active);alter table public.organization_directory enable row level security;grant select on public.organization_directory to anon,authenticated;grant insert,update,delete on public.organization_directory to authenticated;
drop policy if exists organization_directory_public_read on public.organization_directory;create policy organization_directory_public_read on public.organization_directory for select to anon,authenticated using(is_active=true);
drop policy if exists organization_directory_staff_write on public.organization_directory;create policy organization_directory_staff_write on public.organization_directory for insert to authenticated with check(public.has_any_role(array['super_admin','regional_manager']::public.app_role[]));
drop policy if exists organization_directory_staff_update on public.organization_directory;create policy organization_directory_staff_update on public.organization_directory for update to authenticated using(public.has_any_role(array['super_admin','regional_manager']::public.app_role[])) with check(public.has_any_role(array['super_admin','regional_manager']::public.app_role[]));
drop policy if exists organization_directory_staff_delete on public.organization_directory;create policy organization_directory_staff_delete on public.organization_directory for delete to authenticated using(public.has_any_role(array['super_admin','regional_manager']::public.app_role[]));